    private void setupPopupMenu()
    {
        popupMenu = new JPopupMenu();
        popupTitle = new JLabel("");
        popupTitle.setBorder(new EmptyBorder(2, 6, 2, 6));
        popupTitle.setFont(FontManager.getRunescapeBoldFont());
