            {
                name = primary.getName();
            }

            if (selected.size() > 1)
            {
                name = "[" + selected.size() + " Objects Selected]";
            }
        }

        g.setFont(new Font(FontManager.getRunescapeBoldFont().getName(), Font.PLAIN, 64));
        g.setColor(new Color(77, 77, 77, 50));
