                                    idleLeft.setValue(WeaponAnimData.getAnimation(weaponAnim, PlayerAnimationType.IDLE_ROTATE_LEFT));
                                    foundMatch = true;
                                    break;
                                }
                            }

                            if (foundMatch)
                            {
                                break;
                            }
                        }

                        if (!foundMatch)
                        {
                            idle.setValue(-1);
                            walk.setValue(-1);
                            run.setValue(-1);
                            walk180.setValue(-1);
                            walkRight.setValue(-1);
                            walkLeft.setValue(-1);
