                    {
                        comboBox.setVisible(true);
                        selectedCharacter.getModelSpinner().setVisible(false);
                    }
                }

                selectedCharacter.setStoredModel(model);
                selectedCharacter.setToBaseModel(client, clientThread, true, -1);
            }
        }
