        newSetupButton.setBackground(ColorScheme.DARK_GRAY_COLOR);
        newSetupButton.addActionListener(e -> tree.getToolBox().createNewSetup(true, false));
        folderHeader.add(newSetupButton, c);

        return folderHeader;
    }
