    private void addModel(boolean addObject, boolean addAnimationKeyframe)
    {
        if (selectedType == null)
        {
            return;
        }

        String name = "Unnamed";
        int id = 0;
        int size = 1;
        int animId = -1;
        AnimationKeyFrame akf = null;

        switch (selectedType)
        {
            case CACHE_NPC:
                Object npc = npcTable.getSelectedObject();
                if (npc instanceof NpcDefinition)
                {
                    NpcDefinition data = (NpcDefinition) npc;
                    name = data.getName();
                    id = data.getId();
                    size = data.getSize();
                    animId = data.getStandingAnimation();

                    if (addAnimationKeyframe)
                    {
                        akf = new AnimationKeyFrame(
                                plugin.getCurrentTick(),
                                false,
                                -1,
                                0,
                                false,
                                false,
                                data.getStandingAnimation(),
                                data.getWalkingAnimation(),
                                data.getRunAnimation(),
                                data.getRotate180Animation(),
                                data.getRotateRightAnimation(),
                                data.getRotateLeftAnimation(),
                                data.getIdleRotateRightAnimation(),
                                data.getIdleRotateRightAnimation());
                    }
                }
                break;
            case CACHE_OBJECT:
                Object obj = objectTable.getSelectedObject();
                if (obj instanceof ObjectDefinition)
                {
                    ObjectDefinition data = (ObjectDefinition) obj;
                    name = data.getName();
                    id = data.getId();
                    animId = data.getAnimationID();

                    if (addAnimationKeyframe)
                    {
                        akf = new AnimationKeyFrame(
                                plugin.getCurrentTick(),
                                false,
                                -1,
                                0,
                                false,
                                false,
                                data.getAnimationID(),
                                -1,
                                -1,
                                -1,
                                -1,
                                -1,
                                -1,
                                -1);
                    }
                }
                break;
            case CACHE_GROUND_ITEM:
            case CACHE_MAN_WEAR:
            case CACHE_WOMAN_WEAR:
                Object item = itemTable.getSelectedObject();
                if (item instanceof ItemDefinition)
                {
                    ItemDefinition data = (ItemDefinition) item;
                    name = data.getName();
                    id = data.getId();
                }
                break;
            case CACHE_SPOTANIM:
                Object sa = spotAnimTable.getSelectedObject();
                if (sa instanceof SpotAnimDefinition)
                {
                    SpotAnimDefinition data = (SpotAnimDefinition) sa;
                    name = data.getName();
                    id = data.getId();
                    animId = data.getAnimationId();

                    if (addAnimationKeyframe)
                    {
                        akf = new AnimationKeyFrame(
                                plugin.getCurrentTick(),
                                false,
                                -1,
                                0,
                                false,
                                false,
                                data.getAnimationId(),
                                -1,
                                -1,
                                -1,
                                -1,
                                -1,
                                -1,
                                -1);
                    }
                }
        }

        if (!defaultAnimations.isSelected())
        {
            Object anim = animTable.getSelectedObject();
            if (anim instanceof AnimData)
            {
                AnimData data = (AnimData) anim;
                animId = data.getId();
            }
        }

        modelUtilities.cacheToCustomModel(selectedType, id, -1, size, name, animId, addObject, akf);
    }

    private void addToAnvil()
    {
        if (selectedType == null)
        {
            return;
        }

        int id = 0;
        String name = "Name";

        switch (selectedType)
        {
            case CACHE_NPC:
                Object npc = npcTable.getSelectedObject();
                if (npc instanceof NpcDefinition)
                {
                    NpcDefinition data = (NpcDefinition) npc;
                    id = data.getId();
                    name = data.getName();
                }
                break;
            case CACHE_OBJECT:
                Object obj = objectTable.getSelectedObject();
                if (obj instanceof ObjectDefinition)
                {
                    ObjectDefinition data = (ObjectDefinition) obj;
                    id = data.getId();
                    name = data.getName();
                }
                break;
            case CACHE_GROUND_ITEM:
            case CACHE_MAN_WEAR:
            case CACHE_WOMAN_WEAR:
                Object item = itemTable.getSelectedObject();
                if (item instanceof ItemDefinition)
                {
                    ItemDefinition data = (ItemDefinition) item;
                    id = data.getId();
                    name = data.getName();
                }
                break;
            case CACHE_SPOTANIM:
                Object sa = spotAnimTable.getSelectedObject();
                if (sa instanceof SpotAnimDefinition)
                {
                    SpotAnimDefinition data = (SpotAnimDefinition) sa;
                    id = data.getId();
                    name = data.getName();
                }
        }

        boolean renderAll = false;
        int modelId = 0;

        Object o = modelTable.getSelectedObject();
        if (o == null)
        {
            modelUtilities.cacheToAnvil(selectedType, id, name, true, -1);
            return;
        }

        if (o instanceof String)
        {
            String s = (String) o;
            if (s.equals("All"))
            {
                renderAll = true;
            }
        }

        if (o instanceof Integer)
        {
            modelId = (Integer) o;
        }

        modelUtilities.cacheToAnvil(selectedType, id, name, renderAll, modelId);
    }

    private void export3DModel()
    {
        if (selectedType == null)
        {
            return;
        }

        int id = 0;
        String name = "Unnamed";

        switch (selectedType)
        {
            case CACHE_NPC:
                Object npc = npcTable.getSelectedObject();
                if (npc instanceof NpcDefinition)
                {
                    NpcDefinition data = (NpcDefinition) npc;
                    name = data.getName();
                    id = data.getId();
                }
                break;
            case CACHE_OBJECT:
                Object obj = objectTable.getSelectedObject();
                if (obj instanceof ObjectDefinition)
                {
                    ObjectDefinition data = (ObjectDefinition) obj;
                    name = data.getName();
                    id = data.getId();
                }
                break;
            case CACHE_GROUND_ITEM:
            case CACHE_MAN_WEAR:
            case CACHE_WOMAN_WEAR:
                Object item = itemTable.getSelectedObject();
                if (item instanceof ItemDefinition)
                {
                    ItemDefinition data = (ItemDefinition) item;
                    name = data.getName();
                    id = data.getId();
                }
                break;
            case CACHE_SPOTANIM:
                Object sa = spotAnimTable.getSelectedObject();
                if (sa instanceof SpotAnimDefinition)
                {
                    SpotAnimDefinition data = (SpotAnimDefinition) sa;
                    name = data.getName();
                    id = data.getId();
                }
        }

        ModelGetter modelGetter = plugin.getModelGetter();
        boolean renderAll = false;
        int modelId = 0;

        Object o = modelTable.getSelectedObject();
        if (o == null)
        {
            modelGetter.exportModelFromCache(selectedType, id, name, true, -1);;
            return;
        }

        if (o instanceof String)
        {
