            if (s.equals("All"))
            {
                renderAll = true;
            }
        }

        if (o instanceof Integer)
        {
            modelId = (Integer) o;
        }

        modelGetter.exportModelFromCache(selectedType, id, name, renderAll, modelId);
    }
