    public void loadTransmog(File file, TransmogLoadOption transmogLoadOption)
    {
        CreatorsPanel creatorsPanel = plugin.getCreatorsPanel();
        TransmogPanel transmogPanel = creatorsPanel.getToolBox().getTransmogPanel();

        try
        {
            Reader reader = Files.newBufferedReader(file.toPath());
            TransmogSave transmogSave = gson.fromJson(reader, TransmogSave.class);
            CustomModelComp comp = transmogSave.getCustomModelComp();
            if (comp != null)
            {
                DetailedModel[] detailedModels = comp.getDetailedModels();
                if (detailedModels == null)
                {
                    detailedModels = creatorsPanel.getModelOrganizer().modelToDetailedPanels(comp);
                    comp.setDetailedModels(detailedModels);
                }

                if (comp.getRenderMode() == null)
                {
                    int renderMode = Renderable.RENDERMODE_DEFAULT;
                    CustomModelType type = comp.getType();
                    switch (type)
                    {
                        case CACHE_PLAYER:
                        case FORGED:
                        case BLENDER:
                            renderMode = Renderable.RENDERMODE_SORTED_NO_DEPTH;
                    }

                    comp.setRenderMode(renderMode);
                }

                if (comp.getWidthScale() == null || comp.getHeightScale() == null)
                {
                    comp.setWidthScale(128);
                    comp.setHeightScale(128);
                }
            }

            reader.close();

            boolean loadCustomModel = false;
            switch (transmogLoadOption)
            {
                case ANIMATIONS:
                    transmogPanel.loadTransmog(transmogSave);
                    break;
                case CUSTOM_MODEL:
                    if (comp != null)
                        loadCustomModel = true;
                    break;
                case BOTH:
                    transmogPanel.loadTransmog(transmogSave);
                    if (comp != null)
                        loadCustomModel = true;
            }

            if (loadCustomModel)
            {
                clientThread.invokeLater(() ->
                {
                    CustomLighting cl = comp.getCustomLighting();
                    if (cl == null)
                    {
                        cl = CustomLighting.fromLightingStyle(LightingStyle.DEFAULT);
                    }

                    Model model = createComplexModel(comp.getDetailedModels(), comp.isPriority(), cl, false);
                    CustomModel customModel = new CustomModel(model, comp);
                    addCustomModels(new CustomModel[]{customModel}, false);
                    transmogPanel.setTransmog(customModel);
                });
            }
        }
        catch (Exception e)
        {
            sendChatMessage("Failed to load the selected Transmog. Make sure you selected an appropriate transmog file.");
        }
    }

    public void addCustomModels(CustomModel[] models, boolean setComboBox)
    {
        SwingUtilities.invokeLater(() -> plugin.getCreatorsPanel().addModelOptions(models, setComboBox));

        for (CustomModel customModel : models)
        {
            plugin.getStoredModels().add(customModel);
        }
    }

    public void removeCustomModels(CustomModel[] models)
    {
        plugin.getCreatorsPanel().removeModelOptions(models);

        for (CustomModel customModel : models)
        {
            plugin.getStoredModels().remove(customModel);
        }
    }

    public void clearCustomModels()
    {
        ArrayList<CustomModel> models = plugin.getStoredModels();
        plugin.getCreatorsPanel().removeModelOptions(models.toArray(new CustomModel[0]));
        plugin.getStoredModels().clear();
    }

    public void updatePanelComboBoxes()
    {
        SwingUtilities.invokeLater(() ->
        {
            for (JComboBox<CustomModel> comboBox : plugin.getCreatorsPanel().getComboBoxes())
                comboBox.updateUI();
        });
    }

    private void sendChatMessage(String message)
    {
        plugin.sendChatMessage(message);
    }
}

package com.creatorskit.models.dataloaders;

import com.creatorskit.models.datatypes.SpotAnimDefinition;
import lombok.extern.slf4j.Slf4j;

import java.nio.BufferUnderflowException;
import java.util.Set;

@Slf4j
public class SpotAnimLoader
{
    public SpotAnimDefinition load(Set<Integer> unknownOpcodes, int id, byte[] b)
    {
        SpotAnimDefinition def = new SpotAnimDefinition();
        InputStream is = new InputStream(b);
        def.id = id;

        while (is.remaining() > 0)
        {
            int offset = is.getOffset();
            int opcode = is.readUnsignedByte();

            if (opcode == 0)
            {
                return def;
            }

            try
            {
                if (!decodeValues(opcode, def, is))
                {
                    if (unknownOpcodes.add(opcode))
                    {
                        log.warn(
                                "Creator's Kit: Unknown SpotAnim opcode {} " +
                                        "(first seen on id={}, offset={})",
                                opcode,
                                id,
                                offset
                        );
                    }

                    return null;
                }
            }
            catch (BufferUnderflowException e)
            {
                return null;
            }
        }

        return def;
    }

    private boolean decodeValues(int opcode, SpotAnimDefinition def, InputStream stream)
    {
        if (opcode == 1)
        {
            def.modelId = stream.readUnsignedShort();
        }
        else if (opcode == 2)
        {
            def.animationId = stream.readUnsignedShort();
        }
        else if (opcode == 3)
        {
            def.modelId = stream.readInt();
        }
        else if (opcode == 4)
        {
            def.resizeX = stream.readUnsignedShort();
        }
        else if (opcode == 5)
        {
            def.resizeY = stream.readUnsignedShort();
        }
        else if (opcode == 6)
        {
            def.rotation = stream.readUnsignedShort();
        }
        else if (opcode == 7)
        {
            def.ambient = stream.readUnsignedByte();
        }
        else if (opcode == 8)
        {
            def.contrast = stream.readUnsignedByte();
        }
        else if (opcode == 9)
        {
            def.name = stream.readString();
        }
        else if (opcode == 40)
        {
            int var3 = stream.readUnsignedByte();
            def.recolorToFind = new short[var3];
            def.recolorToReplace = new short[var3];

            for (int var4 = 0; var4 < var3; ++var4)
            {
                def.recolorToFind[var4] = (short) stream.readUnsignedShort();
                def.recolorToReplace[var4] = (short) stream.readUnsignedShort();
            }
        }
        else if (opcode == 41)
        {
            int var3 = stream.readUnsignedByte();
            def.textureToFind = new short[var3];
            def.textureToReplace = new short[var3];

            for (int var4 = 0; var4 < var3; ++var4)
            {
                def.textureToFind[var4] = (short) stream.readUnsignedShort();
                def.textureToReplace[var4] = (short) stream.readUnsignedShort();
            }
        }
        else
        {
            return false;
        }

        return true;
    }
}

