            def.femaleModel1 = stream.readUnsignedShort();
        }
        else if (opcode == 27)
        {
            def.wearPos3 = stream.readByte();
        }
        else if (opcode >= 30 && opcode < 35)
        {
            stream.readString();
        }
        else if (opcode >= 35 && opcode < 40)
        {
            stream.readString();
        }
        else if (opcode == 40)
        {
            int var5 = stream.readUnsignedByte();
            def.colorFind = new short[var5];
