        else if (opcode == 201)
        {
            stream.readUnsignedByte();
            stream.readUnsignedShort();
            stream.readUnsignedShort();
            stream.readInt();
            stream.readInt();
            stream.readString();
        }
        else if (opcode == 202)
        {
            stream.readUnsignedByte();
            stream.readUnsignedShort();
            stream.readUnsignedShort();
            stream.readUnsignedShort();
            stream.readInt();
            stream.readInt();
            stream.readString();
        }
        else if (opcode == 249)
        {
            int count = stream.readUnsignedByte();

            for (int i = 0; i < count; i++)
            {
                int type = stream.readUnsignedByte();

                stream.read24BitInt();

                if (type == 1)
                {
                    stream.readString();
                }
                else if (type == 2)
                {
                    stream.readLong();
                }
                else
                {
                    stream.readInt();
                }
            }
        }
        else
        {
            return false;
        }

        return true;
    }
