@AllArgsConstructor
@Getter
public enum LightingStyle
{
    NONE("None", 128, 4000, -50, -50, 10),
    ACTOR("Actor", 64, 850, -30, -30, 50),
    DEFAULT("Default", 64, 768, -50, -50, 10),
    SPOTANIM("SpotAnim", 64, 850, -50, -50, 75),
    DYNAMIC("Dynamic", 100, 850, -10, -10, 10),
    CUSTOM("Custom", 64, 768, -50, -50, 10)
    ;

    private final String string;
    private final int ambient;
    private final int contrast;
    private final int x;
    private final int y;
    private final int z;

    @Override
    public String toString()
    {
        return string;
    }

    public static LightingStyle fromCustomLighting(CustomLighting cl)
    {
        if (cl == null)
        {
            return CUSTOM;
        }

        LightingStyle[] styles = new LightingStyle[]{DEFAULT, ACTOR, SPOTANIM, DYNAMIC, NONE};
        for (LightingStyle ls : styles)
        {
            if (ls.getAmbient() == cl.getAmbient()
                && ls.getContrast() == cl.getContrast()
                && ls.getX() == cl.getX()
                && ls.getY() == cl.getY()
                && ls.getZ() == cl.getZ())
            {
                return ls;
            }
        }

        return CUSTOM;
    }

    public static LightingStyle fromModelType(CustomModelType type)
    {
        switch (type)
        {
            case BLENDER:
            case FORGED:
            case CACHE_PLAYER:
            case CACHE_NPC:
                return ACTOR;
            default:
            case CACHE_OBJECT:
            case CACHE_MAN_WEAR:
            case CACHE_WOMAN_WEAR:
            case CACHE_GROUND_ITEM:
                return DEFAULT;
            case CACHE_SPOTANIM:
                return SPOTANIM;

        }
    }
}

