        handleStoreOptions(model, modelStats, menuOption, CustomModelType.CACHE_GROUND_ITEM, name, new int[0], false, model.getRenderMode(), LightingStyle.DEFAULT, 0, -1, null, new SpotAnimKeyFrame[0]);
    }

