    public void addProgramStep()
    {
        Character primary = selectionManager.getPrimary();
        if (primary == null)
        {
            return;
        }

        WorldView worldView = client.getTopLevelWorldView();
        if (worldView == null)
        {
            return;
        }

        Tile tile = worldView.getSelectedSceneTile();
        if (tile == null)
