import net.runelite.api.coords.LocalPoint;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

import javax.inject.Inject;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.ArrayList;

public class HealthOverlay extends Overlay
{
    private final Client client;
    private final CreatorsPlugin plugin;
    private final SpriteManager spriteManager;

    private final int MODEL_HEIGHT_BUFFER = 18;
    private final int Y_BUFFER = -1;
    private final int TEXT_BUFFER = -12;
    private final int X_BUFFER = -1;

    @Inject
    private HealthOverlay(Client client, CreatorsPlugin plugin, SpriteManager spriteManager)
    {
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
        this.client = client;
        this.plugin = plugin;
        this.spriteManager = spriteManager;
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            return null;
        }

        graphics.setFont(FontManager.getRunescapeSmallFont());

        ArrayList<com.creatorskit.Character> characters = plugin.getCharacters();
        for (int i = 0; i < characters.size(); i++)
        {
            Character character = characters.get(i);
            if (!character.isActive())
            {
                continue;
            }

            HealthKeyFrame healthKeyFrame = (HealthKeyFrame) character.getCurrentKeyFrame(KeyFrameType.HEALTH);
            if (healthKeyFrame == null)
            {
                continue;
            }

            CKObject ckObject = character.getCkObject();
            if (!ckObject.isActive())
            {
                continue;
            }

            LocalPoint lp = ckObject.getLocation();
            if (lp == null || !lp.isInScene())
            {
                continue;
            }

            BufferedImage redBar = spriteManager.getSprite(healthKeyFrame.getHealthbarSprite().getBackgroundSpriteID(), 0);
            if (redBar == null)
            {
                continue;
            }

            BufferedImage greenBar = spriteManager.getSprite(healthKeyFrame.getHealthbarSprite().getForegroundSpriteID(), 0);
            if (greenBar == null)
            {
                continue;
            }

            double duration = healthKeyFrame.getDuration();
            double startTick = healthKeyFrame.getTick();
            double currentTick = plugin.getCurrentTick();
            if (currentTick > duration + startTick)
            {
                continue;
            }

            double ratio = (double) healthKeyFrame.getCurrentHealth() / (double) healthKeyFrame.getMaxHealth();
            int barWidth = (int) (ratio * redBar.getWidth());
            if (barWidth == 0 && ratio > 0)
            {
                barWidth = 1;
            }

            if (barWidth > greenBar.getWidth())
            {
                barWidth = greenBar.getWidth();
            }

            Model model = ckObject.getModel();
            if (model == null)
            {
                continue;
            }

            model.calculateBoundsCylinder();
            int height = model.getModelHeight();

            int textBuffer = 0;
            TextKeyFrame textKeyFrame = (TextKeyFrame) character.getCurrentKeyFrame(KeyFrameType.TEXT);
            if (textKeyFrame != null)
            {
                double textDuration = textKeyFrame.getDuration();
                double textStartTick = textKeyFrame.getTick();
                if (currentTick <= textDuration + textStartTick)
                {
                    textBuffer = TEXT_BUFFER;
                }
            }

            Point base = Perspective.getCanvasImageLocation(client, lp, redBar, height + MODEL_HEIGHT_BUFFER);
            if (base == null)
            {
                continue;
            }

            Point p = new Point(base.getX() + X_BUFFER, base.getY() + Y_BUFFER + textBuffer);

            OverlayUtil.renderImageLocation(graphics, p, redBar);

            if (barWidth > 0)
            {
                BufferedImage subImage = greenBar.getSubimage(0, 0, barWidth, redBar.getHeight());
                OverlayUtil.renderImageLocation(graphics, p, subImage);
            }
        }

        return null;
    }
}

package com.creatorskit.programming;

import com.creatorskit.CreatorsConfig;
import com.creatorskit.swing.timesheet.keyframe.subtypes.MovementKeyFrame;
import net.runelite.api.Client;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import org.apache.commons.lang3.ArrayUtils;

import javax.inject.Inject;
import java.util.Arrays;

public class MovementManager
{
    private Client client;
    private CreatorsConfig config;
    private PathFinder pathFinder;
    private static final int[] POH_REGIONS = new int[]{7534, 7535, 7790, 7791, 8046, 8047, 8302, 8303};
    private static final int[] GAUNTLET_REGIONS = new int[]{7512, 7768};

    @Inject
    public MovementManager(Client client, CreatorsConfig config, PathFinder pathFinder)
    {
        this.client = client;
        this.config = config;
        this.pathFinder = pathFinder;
    }

    public int[][] addProgramStep(MovementKeyFrame keyFrame, WorldView worldView, LocalPoint localPoint)
    {
        if (localPoint == null)
        {
            return new int[0][2];
        }

        if (useLocalLocations(worldView))
        {
            return addPOHStep(keyFrame, worldView, localPoint);
        }

        return addWorldStep(keyFrame, worldView, WorldPoint.fromLocalInstance(client, localPoint));
    }

    public int[][] addWorldStep(MovementKeyFrame keyFrame, WorldView worldView, WorldPoint worldPoint)
    {
        int[][] path = keyFrame.getPath();
        if (path.length == 0)
        {
            return new int[][]{new int[]{worldPoint.getX(), worldPoint.getY()}};
        }

        int[] lastStep = path[path.length - 1];
        int[][] stepsToAdd = pathFinder.findPath(worldView, new WorldPoint(lastStep[0], lastStep[1], worldView.getPlane()), worldPoint, config.movementAlgorithm());

        return ArrayUtils.addAll(path, stepsToAdd);
    }

    public int[][] addPOHStep(MovementKeyFrame keyFrame, WorldView worldView, LocalPoint localPoint)
    {
        int[][] path = keyFrame.getPath();
        if (path.length == 0)
        {
            return new int[][]{new int[]{localPoint.getSceneX(), localPoint.getSceneY()}};
        }

        int[] lastStep = path[path.length - 1];
        int[][] stepsToAdd = pathFinder.findPath(LocalPoint.fromScene(lastStep[0], lastStep[1], worldView), localPoint, config.movementAlgorithm());

        return ArrayUtils.addAll(path, stepsToAdd);
    }

    public static boolean useLocalLocations(WorldView worldView)
    {
        int[] mapRegions = worldView.getMapRegions();
        if (mapRegions == null)
        {
            return false;
        }

        if (Arrays.stream(worldView.getMapRegions()).anyMatch(x -> Arrays.stream(POH_REGIONS).anyMatch(y -> y == x)))
        {
            return true;
        }

        if (Arrays.stream(worldView.getMapRegions()).anyMatch(x -> Arrays.stream(GAUNTLET_REGIONS).anyMatch(y -> y == x)))
        {
            return true;
        }

        return false;
    }
}

package com.creatorskit.programming.camera;

import com.creatorskit.Character;
import com.creatorskit.programming.MovementManager;
import com.creatorskit.swing.timesheet.keyframe.KeyFrameType;
import com.creatorskit.swing.timesheet.keyframe.subtypes.MovementKeyFrame;
import net.runelite.api.Client;
import net.runelite.api.Constants;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;

public class Ease
{
    public static CameraDirectionalScript interpolateTileTracking(boolean isInPOH, double ratio, EaseType easeType, CameraDirectionalScript currentScript, CameraDirectionalScript nextScript)
    {
        if (nextScript == null)
        {
            return currentScript;
        }

        double interpolationFactor = calculateEasing(easeType, ratio);

        double currentYaw = currentScript.getYaw();
        double nextYaw = nextScript.getYaw();

        double yawDiff = nextYaw - currentYaw;
        if (Math.abs(yawDiff) > 8192) {
            if (yawDiff > 0) {
                currentYaw += 16384;
            } else {
                nextYaw += 16384;
            }
        }

        return new CameraDirectionalScript(
                CameraMotionType.TILE_TRACKING,
                currentScript.getEase(),
                lerp(currentScript.getPitch(), nextScript.getPitch(), interpolationFactor),
                lerp(currentYaw, nextYaw, interpolationFactor) % 16384,
                (int) lerp(currentScript.getScale(), nextScript.getScale(), interpolationFactor),
                isInPOH,
                (float) lerp(currentScript.getFocalX(), nextScript.getFocalX(), interpolationFactor),
                0,
                (float) lerp(currentScript.getFocalY(), nextScript.getFocalY(), interpolationFactor),
                (float) lerp(currentScript.getFocalZ(), nextScript.getFocalZ(), interpolationFactor),
                0
        );
    }

    public static Float interpolateObjectTrackingHeight(Client client, double currentTick, boolean playing, Character c, double modelHeight)
    {
        MovementKeyFrame keyFrame = (MovementKeyFrame) c.getCurrentKeyFrame(KeyFrameType.MOVEMENT);
        if (keyFrame == null)
        {
            return null;
        }

        WorldView worldView = client.getTopLevelWorldView();

        int currentStep = keyFrame.getCurrentStep();
        int[][] path = keyFrame.getPath();
        if (currentStep >= path.length)
        {
            currentStep = path.length - 1;
        }

        int[] current = path[currentStep];
        boolean inPOH = MovementManager.useLocalLocations(worldView);
        int pohFactor = 0;
        if (inPOH)
        {
            pohFactor = -232;
        }

        LocalPoint lp;
        if (inPOH)
        {
            lp = new LocalPoint(current[0], current[1], worldView);
        }
        else
        {
            lp = LocalPoint.fromWorld(worldView, new WorldPoint(current[0], current[1], worldView.getPlane()));
        }

        if (lp == null)
        {
            return null;
        }

        int currentTileHeight = worldView.getTileHeight(lp.getX(), lp.getY(), worldView.getPlane());
        float calculatedModelHeight = (float) (-0.55 * modelHeight);

        if (currentStep == path.length - 1)
        {
            return (float) currentTileHeight + calculatedModelHeight + pohFactor;
        }

        int[] next = path[currentStep + 1];
        LocalPoint nextLp;
        if (inPOH)
        {
            nextLp = new LocalPoint(next[0], next[1], worldView);
        }
        else
        {
            nextLp = LocalPoint.fromWorld(worldView, new WorldPoint(next[0], next[1], worldView.getPlane()));
        }

        if (nextLp == null)
        {
            return (float) currentTileHeight + calculatedModelHeight + pohFactor;
        }

        int nextTileHeight = worldView.getTileHeight(nextLp.getX(), nextLp.getY(), worldView.getPlane());
        double percentComplete = calculatePercentStepComplete(keyFrame, currentTick, client.getGameCycle(), currentStep, playing);
        double tileHeight = percentComplete * (nextTileHeight - currentTileHeight) + currentTileHeight;

        return (float) (tileHeight + calculatedModelHeight + pohFactor);
    }

    private static double calculatePercentStepComplete(MovementKeyFrame keyFrame, double currentTick, int gameCycle, int currentStep, boolean playing)
    {
        if (playing)
        {
            double tileSpeed = keyFrame.getSpeed();
            double speed = tileSpeed * Constants.CLIENT_TICK_LENGTH / Constants.GAME_TICK_LENGTH;
            int clientTicksPassed = gameCycle - keyFrame.getStepClientTick();
            double stepsComplete = clientTicksPassed * speed;
            return Math.abs(stepsComplete - currentStep);
        }

        int[][] path = keyFrame.getPath();
        int pathLength = path.length;

        double tileSpeed = keyFrame.getSpeed();
        double timePassed = currentTick - keyFrame.getTick();
        double stepsComplete = timePassed * tileSpeed;
        currentStep = (int) Math.floor(stepsComplete);
        double endSpeed = (pathLength - 1) - (Math.floor(((pathLength - 1) / tileSpeed)) * tileSpeed);

        if (stepsComplete + endSpeed > pathLength - 1)
        {
            double jumps = (pathLength - 1) % tileSpeed;
            if (jumps != 0)
            {
                double ticksPreSlowdown = (pathLength - 1 - endSpeed) / tileSpeed;
                double stepsPreSlowdown = ticksPreSlowdown * tileSpeed;

                stepsComplete = (timePassed - ticksPreSlowdown) * endSpeed + stepsPreSlowdown;
                currentStep = (int) (stepsComplete);
            }
        }

        if (currentStep > pathLength)
        {
            currentStep = pathLength;
        }

        return Math.abs(stepsComplete - currentStep);
    }

    public static CameraTrackingScript interpolateObjectTracking(double ratio, EaseType easeType, Character character, CameraTrackingScript currentScript, CameraTrackingScript nextScript)
    {
        if (nextScript == null)
        {
            return currentScript;
        }

        double interpolationFactor = calculateEasing(easeType, ratio);

        double currentYaw = currentScript.getYaw();
        double nextYaw = nextScript.getYaw();

        double yawDiff = nextYaw - currentYaw;
        if (Math.abs(yawDiff) > 8192) {
            if (yawDiff > 0) {
                currentYaw += 16384;
            } else {
                nextYaw += 16384;
            }
        }

        return new CameraTrackingScript(
                CameraMotionType.OBJECT_TRACKING,
                currentScript.getEase(),
                lerp(currentScript.getPitch(), nextScript.getPitch(), interpolationFactor),
                lerp(currentYaw, nextYaw, interpolationFactor) % 16384,
                (int) lerp(currentScript.getScale(), nextScript.getScale(), interpolationFactor),
                character
        );
    }

    public static double lerp(double start, double end, double t) {
        return start + (end - start) * t;
    }

    private static double calculateEasing(EaseType ease, double t) {
        switch (ease) {
            case LINEAR:
                return t;
            case SINE:
                return sinEaseInOut(t);
            case QUAD:
                return quadEaseInOut(t);
            case CUBIC:
                return cubicEaseInOut(t);
            case QUART:
                return quartEaseInOut(t);
            case QUINT:
                return quintEaseInOut(t);
            case EXPO:
                return expoEaseInOut(t);
            case EASE_IN_CUBIC:
                return cubicEaseIn(t);
            case EASE_IN_SINE:
                return sineEaseIn(t);
            case EASE_IN_QUAD:
                return quadEaseIn(t);
            case EASE_IN_QUART:
                return quartEaseIn(t);
            case EASE_IN_QUINT:
                return quintEaseIn(t);
            case EASE_OUT_SINE:
                return sineEaseOut(t);
            case EASE_OUT_CUBIC:
                return cubicEaseOut(t);
            case EASE_OUT_QUAD:
                return quadEaseOut(t);
            case EASE_OUT_QUART:
                return quartEaseOut(t);
            case EASE_OUT_QUINT:
                return quintEaseOut(t);

            default:
                throw new IllegalArgumentException("Unknown easing type: " + ease);
        }
    }

    // Easing functions
    private static double sinEaseInOut(double t) { return (-(Math.cos(Math.PI * t) - 1) / 2); }

    private static double quadEaseInOut(double t) {
        return t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
    }

    private static double cubicEaseInOut(double t) {
        return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
    }

    private static double quartEaseInOut(double t) {
        return t < 0.5 ? 8 * t * t * t * t : 1 - Math.pow(-2 * t + 2, 4) / 2;
    }

    private static double quintEaseInOut(double t) {
        return t < 0.5 ? 16 * t * t * t * t * t : 1 - Math.pow(-2 * t + 2, 5) / 2;
    }

    private static double expoEaseInOut(double t) {
        return t == 0 ? 0 : t == 1 ? 1 : t < 0.5 ? Math.pow(2, 20 * t - 10) / 2
                : (2 - Math.pow(2, -20 * t + 10)) / 2;
    }

    private static double sineEaseIn(double t) {
        return 1 - Math.cos((t * Math.PI) / 2);
    }

    private static double quadEaseIn(double t) {
        return t * t;
    }

    private static double cubicEaseIn(double t) {
        return t * t * t;
    }

    private static double quartEaseIn(double t) {
        return t * t * t * t;
    }

    private static double quintEaseIn(double t) {
        return t * t * t * t * t;
    }

    private static double sineEaseOut(double t) {
        return Math.sin((t * Math.PI) / 2);
    }

    private static double quadEaseOut(double t) {
        return 1 - Math.pow(1 - t, 2);
    }

    private static double cubicEaseOut(double t) {
        return 1 - Math.pow(1 - t, 3);
    }

    private static double quartEaseOut(double t) {
        return 1 - Math.pow(1 - t, 4);
    }

    private static double quintEaseOut(double t) {
        return 1 - Math.pow(1 - t, 5);
    }
}

package com.creatorskit.programming.camera;

import com.creatorskit.CKObject;
import com.creatorskit.Character;
import com.creatorskit.programming.MovementManager;
import com.creatorskit.saves.CameraScriptSave;
import com.creatorskit.swing.timesheet.keyframe.KeyFrame;
import com.creatorskit.swing.timesheet.keyframe.subtypes.CameraKeyFrame;
import lombok.Getter;
import lombok.Setter;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.ScriptID;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.callback.ClientThread;
import org.apache.commons.lang3.ArrayUtils;

import javax.inject.Inject;
import java.util.List;

public class CameraManager
{
    private final Client client;
    private ClientThread clientThread;

    private CameraKeyFrame currentKeyFrame;
    private CameraKeyFrame nextKeyFrame;
    private int clientTicksPassed = 0;
    private final static int CLIENT_TO_GAME_TICK_RATIO = 30;

    @Getter
    private KeyFrame[] keyFrames = new CameraKeyFrame[0];
    @Setter
    private boolean enabled = true;
    @Setter
    private boolean cancelled = false;

    @Inject
    public CameraManager(Client client, ClientThread clientThread)
    {
        this.client = client;
        this.clientThread = clientThread;
    }

    /**
     * Ticks the camera timer for interpolating between GameTicks. Intended for use when Playing the programmer, not when manually setting the time
     */
    public void tick()
    {
        clientTicksPassed++;

        if (currentKeyFrame == null)
        {
            return;
        }

        if (nextKeyFrame == null)
        {
            handleCameraScript(true, 0);
            return;
        }

        handleCameraScript(true, 0);
    }

    /**
     * Updates the active camera keyframe. Intended for use when playing the program
     */
    public void updateProgramOnTick(double currentTick)
    {
        KeyFrame current = getCurrentKeyFrame(currentTick);
        if (current == null)
        {
            clientTicksPassed = 0;
            currentKeyFrame = null;
            nextKeyFrame = null;
            return;
        }

        if (current != currentKeyFrame)
        {
            clientTicksPassed = 0;
            currentKeyFrame = (CameraKeyFrame) current;
        }

        if (currentKeyFrame.getTick() > currentTick)
        {
            clientTicksPassed = 0;
            nextKeyFrame = null;
            return;
        }

        KeyFrame next = getNextKeyFrame(currentTick);
        if (next == null)
        {
            nextKeyFrame = null;
            return;
        }

        nextKeyFrame = (CameraKeyFrame) next;
    }

    /**
     * Updates the active camera keyframe. Intended for use when manually setting the time
     */
    public void updateProgram(double currentTick, boolean playing)
    {
        cancelled = false;
        KeyFrame current = getCurrentKeyFrame(currentTick);
        if (current == null)
        {
            clientTicksPassed = 0;
            currentKeyFrame = null;
            nextKeyFrame = null;
            return;
        }

        if (current != currentKeyFrame)
        {
            clientTicksPassed = 0;
            currentKeyFrame = (CameraKeyFrame) current;
        }

        if (currentKeyFrame.getTick() > currentTick)
        {
            nextKeyFrame = null;
            handleCameraScript(playing, currentKeyFrame.getTick());
            return;
        }

        KeyFrame next = getNextKeyFrame(currentTick);
        if (next == null)
        {
            nextKeyFrame = null;
            handleCameraScript(playing, currentTick);
            return;
        }

        nextKeyFrame = (CameraKeyFrame) next;
        clientTicksPassed = (int) ((currentTick - currentKeyFrame.getTick()) * CLIENT_TO_GAME_TICK_RATIO);
        handleCameraScript(playing, currentTick);
    }

    private void handleCameraScript(boolean playing, double currentTick)
    {
        if (!enabled || cancelled || client.getCameraMode() != 1)
        {
            return;
        }

        if (currentKeyFrame == null)
        {
            return;
        }

        CameraScript currentScript = currentKeyFrame.getScript();
        if (currentScript.getType() == CameraMotionType.TILE_TRACKING)
        {
            CameraDirectionalScript currentDirectionalScript = (CameraDirectionalScript) currentScript;
            handleDirectionalScript(currentDirectionalScript);
            return;
        }

        CameraTrackingScript currentTrackingScript = (CameraTrackingScript) currentScript;
        handleTrackingScript(currentTrackingScript, playing, currentTick);
    }

    private void handleDirectionalScript(CameraDirectionalScript currentDirectionalScript)
    {
        boolean inPOH = MovementManager.useLocalLocations(client.getTopLevelWorldView());
        if (!inPOH && currentDirectionalScript.isInPOH() || inPOH && !currentDirectionalScript.isInPOH())
        {
            return;
        }

        CameraDirectionalScript convertedCurrent = CameraUtilities.readCameraScript(inPOH, client.getTopLevelWorldView(), currentDirectionalScript);
        if (convertedCurrent == null)
        {
            return;
        }

        CameraDirectionalScript nextScript;
        if (nextKeyFrame == null || nextKeyFrame.getScript().getType() == CameraMotionType.OBJECT_TRACKING)
        {
            setCamera(convertedCurrent.getFocalX(), convertedCurrent.getFocalY(), convertedCurrent.getFocalZ(), (int) convertedCurrent.getPitch(), (int) convertedCurrent.getYaw(), convertedCurrent.getScale());
            return;
        }
        else
        {
            nextScript = (CameraDirectionalScript) nextKeyFrame.getScript();
        }

        if (!inPOH && nextScript.isInPOH() || inPOH && !nextScript.isInPOH())
        {
            setCamera(convertedCurrent.getFocalX(), convertedCurrent.getFocalY(), convertedCurrent.getFocalZ(), (int) convertedCurrent.getPitch(), (int) convertedCurrent.getYaw(), convertedCurrent.getScale());
            return;
        }

        CameraDirectionalScript convertedNext = CameraUtilities.readCameraScript(inPOH, client.getTopLevelWorldView(), nextScript);
        if (convertedNext == null)
        {
            setCamera(convertedCurrent.getFocalX(), convertedCurrent.getFocalY(), convertedCurrent.getFocalZ(), (int) convertedCurrent.getPitch(), (int) convertedCurrent.getYaw(), convertedCurrent.getScale());
            return;
        }

        double ratio = ((double) clientTicksPassed / CLIENT_TO_GAME_TICK_RATIO) / (nextKeyFrame.getTick() - currentKeyFrame.getTick());
        CameraDirectionalScript script = Ease.interpolateTileTracking(MovementManager.useLocalLocations(client.getTopLevelWorldView()), ratio, convertedCurrent.getEase(), convertedCurrent, convertedNext);
        setCamera(script.getFocalX(), script.getFocalY(), script.getFocalZ(), (int) script.getPitch(), (int) script.getYaw(), script.getScale());
    }

    private void handleTrackingScript(CameraTrackingScript currentTrackingScript, boolean playing, double currentTick)
    {
        Character character = currentTrackingScript.getCharacter();
        if (character == null || !character.isInScene())
        {
            return;
        }

        CKObject ckObject = character.getCkObject();
        if (ckObject == null)
        {
            return;
        }

        LocalPoint lp = ckObject.getLocation();

        Model model = ckObject.getBaseModel();
        if (model == null)
        {
            return;
        }

        model.calculateBoundsCylinder();
        Float height = Ease.interpolateObjectTrackingHeight(client, currentTick, playing, character, model.getModelHeight());
        if (height == null)
        {
            return;
        }

        CameraTrackingScript nextScript;
        if (nextKeyFrame == null || nextKeyFrame.getScript().getType() == CameraMotionType.TILE_TRACKING)
        {
            setCamera(
                    lp.getX(),
                    height,
                    lp.getY(),
                    (int) currentTrackingScript.getPitch(),
                    (int) currentTrackingScript.getYaw(),
                    currentTrackingScript.getScale());
            return;
        }
        else
        {
            nextScript = (CameraTrackingScript) nextKeyFrame.getScript();
        }

        double ratio = ((double) clientTicksPassed / CLIENT_TO_GAME_TICK_RATIO) / (nextKeyFrame.getTick() - currentKeyFrame.getTick());
        CameraTrackingScript script = Ease.interpolateObjectTracking(ratio, currentTrackingScript.getEase(), character, currentTrackingScript, nextScript);
        setCamera(
                lp.getX(),
                height,
                lp.getY(),
                (int) script.getPitch(),
                (int) script.getYaw(),
                script.getScale());
    }

    private void setCamera(float x, float y, float z, int pitch, int yaw, int scale)
    {
        client.setCameraFocalPointX(x);
        client.setCameraFocalPointY(y);
        client.setCameraFocalPointZ(z);
        client.setCameraPitchTarget(pitch);
        client.setCameraYawTarget(yaw);
        clientThread.invokeLater(() -> client.runScript(ScriptID.CAMERA_DO_ZOOM, scale, scale));
    }

    public KeyFrame getCurrentKeyFrame(double currentTick)
    {
        if (keyFrames.length == 0)
        {
            return null;
        }

        if (keyFrames.length == 1)
        {
            return keyFrames[0];
        }

        for (int i = 0; i < keyFrames.length; i++)
        {
            KeyFrame keyFrame = keyFrames[i];

            if (keyFrame.getTick() == currentTick)
            {
                return keyFrame;
            }

            if (keyFrame.getTick() > currentTick)
            {
                if (i == 0)
                {
                    return keyFrame;
                }

                return keyFrames[i - 1];
            }
        }

        return keyFrames[keyFrames.length - 1];
    }

    public KeyFrame getPreviousKeyFrame(boolean includeCurrentTick, double currentTick)
    {
        for (int i = keyFrames.length - 1; i >= 0; i--)
        {
            KeyFrame keyFrame = keyFrames[i];
            if (includeCurrentTick && keyFrame.getTick() == currentTick)
            {
                return keyFrame;
            }

            if (keyFrame.getTick() < currentTick)
            {
                return keyFrame;
            }
        }

        return null;
    }

    public KeyFrame getNextKeyFrame(double currentTick)
    {
        for (int i = 0; i < keyFrames.length; i++)
        {
            KeyFrame keyFrame = keyFrames[i];

            if (keyFrame.getTick() > currentTick)
            {
                return keyFrame;
            }
        }

        return null;
    }

    public KeyFrame addKeyFrame(KeyFrame keyFrame)
    {
        double tick = keyFrame.getTick();

        int index = 0;
        while (index < keyFrames.length && keyFrames[index].getTick() < tick)
        {
            index++;
        }

        if (index < keyFrames.length && keyFrames[index].getTick() == tick)
        {
            KeyFrame toRemove = keyFrames[index];
            keyFrames[index] = keyFrame;
            return toRemove;
        }

        keyFrames = ArrayUtils.insert(index, keyFrames, keyFrame);
        return null;
    }

    public void removeKeyFrame(KeyFrame keyFrame)
    {
        keyFrames = ArrayUtils.removeElement(keyFrames, keyFrame);
    }

    public void clearKeyFrames()
    {
        keyFrames = new KeyFrame[0];
        currentKeyFrame = null;
        nextKeyFrame = null;
    }

    public void onCharacterDeleted(Character c)
    {
        for (int i = 0; i < keyFrames.length; i++)
        {
            CameraKeyFrame keyFrame = (CameraKeyFrame) keyFrames[i];
            CameraScript script = keyFrame.getScript();
            if (script.getType() == CameraMotionType.OBJECT_TRACKING)
            {
                CameraTrackingScript trackingScript = (CameraTrackingScript) script;
                if (trackingScript.getCharacter() == c)
                {
                    trackingScript.setCharacter(null);
                }
            }
        }
    }

    public CameraScriptSave[] packCameraKeyFrames()
    {
        CameraScriptSave[] scriptSaves = new CameraScriptSave[keyFrames.length];
        for (int i = 0; i < keyFrames.length; i++)
        {
            KeyFrame keyFrame = keyFrames[i];
            CameraKeyFrame kf = (CameraKeyFrame) keyFrame;
            if (kf.getScript().getType() == CameraMotionType.TILE_TRACKING)
            {
                CameraDirectionalScript script = (CameraDirectionalScript) kf.getScript();
                CameraScriptSave save = new CameraScriptSave(
                        CameraMotionType.TILE_TRACKING,
                        script.getEase(),
                        script.getPitch(),
                        script.getYaw(),
                        script.getScale(),
                        keyFrame.getTick(),
                        script.isInPOH(),
                        script.getFocalX(),
                        script.getOffsetX(),
                        script.getFocalY(),
                        script.getFocalZ(),
                        script.getOffsetZ(),
                        null
                );
                scriptSaves[i] = save;
            }
            else
            {
                CameraTrackingScript script = (CameraTrackingScript) kf.getScript();
                Character character = script.getCharacter();
                String id = character == null ? "" : character.getId();
                CameraScriptSave save = new CameraScriptSave(
                        CameraMotionType.OBJECT_TRACKING,
                        script.getEase(),
                        script.getPitch(),
                        script.getYaw(),
                        script.getScale(),
                        keyFrame.getTick(),
                        false,
                        0,
                        0,
                        0,
                        0,
                        0,
                        id
                );

                scriptSaves[i] = save;
            }
        }

        return scriptSaves;
    }

    public void unpackCameraKeyFrames(CameraScriptSave[] scriptSaves, List<Character> characters)
    {
        if (scriptSaves == null)
        {
            return;
        }

        for (int i = 0; i < scriptSaves.length; i++)
        {
            CameraScriptSave scriptSave = scriptSaves[i];
            if (scriptSave.getType() == CameraMotionType.TILE_TRACKING)
            {
                CameraDirectionalScript script = new CameraDirectionalScript(
                        CameraMotionType.TILE_TRACKING,
                        scriptSave.getEase(),
                        scriptSave.getPitch(),
                        scriptSave.getYaw(),
                        scriptSave.getScale(),
                        scriptSave.isInPOH(),
                        scriptSave.getFocalX(),
                        scriptSave.getOffsetX(),
                        scriptSave.getFocalY(),
                        scriptSave.getFocalZ(),
                        scriptSave.getOffsetZ()
                );

                addKeyFrame(new CameraKeyFrame(
                        scriptSave.getTick(),
                        script)
                );
            }
            else
            {
                Character character = null;
                String scriptId = scriptSave.getId();
                for (Character c : characters)
                {
                    if (c.getId().equals(scriptId))
                    {
                        character = c;
                        break;
                    }
                }

                CameraTrackingScript script = new CameraTrackingScript(
                        CameraMotionType.OBJECT_TRACKING,
                        scriptSave.getEase(),
                        scriptSave.getPitch(),
                        scriptSave.getYaw(),
                        scriptSave.getScale(),
                        character
                );

                addKeyFrame(new CameraKeyFrame(
                        scriptSave.getTick(),
                        script)
                );
            }
        }
    }
}

