import net.runelite.api.coords.LocalPoint;

@AllArgsConstructor
@Getter
@Setter
public class MovementComposition
{
    private boolean moving;
    private LocalPoint localPoint;
    private OrientationAction orientationAction;
    private int orientationGoal;
    private int orientationToSet;
}

package com.creatorskit.programming;

import com.creatorskit.*;
import com.creatorskit.Character;
import com.creatorskit.hotkeymanager.LocationOption;
import com.creatorskit.models.*;
import com.creatorskit.models.datatypes.SpotAnimDefinition;
import com.creatorskit.programming.camera.CameraManager;
